#include <queue>
#include <string>
#include <utility>
#include <vector>

std::vector<int> distanceMap(const std::string& map, int width, int goalX, int goalY)
{
    const int height{ static_cast<int>(map.size()) / width };
    std::vector<int> dist(map.size(), -1);
    auto index = [width](int x, int y) { return static_cast<std::size_t>(y * width + x); };
    if (goalX < 0 || goalY < 0 || goalX >= width || goalY >= height || map[index(goalX, goalY)] == '#') return dist;
    std::queue<std::pair<int, int>> frontier;
    dist[index(goalX, goalY)] = 0;
    frontier.push({ goalX, goalY });
    const int dx[]{ 0, 0, -1, 1 }, dy[]{ -1, 1, 0, 0 };
    while (!frontier.empty())
    {
        const auto [x, y] = frontier.front();
        frontier.pop();
        for (int d{ 0 }; d < 4; ++d)
        {
            const int nx{ x + dx[d] }, ny{ y + dy[d] };
            if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
            if (map[index(nx, ny)] == '#' || dist[index(nx, ny)] != -1) continue;
            dist[index(nx, ny)] = dist[index(x, y)] + 1;
            frontier.push({ nx, ny });
        }
    }
    return dist;
}

std::pair<int, int> nextStep(const std::string& map, int width, const std::vector<int>& distances, int x, int y)
{
    const int height{ static_cast<int>(map.size()) / width };
    auto index = [width](int px, int py) { return static_cast<std::size_t>(py * width + px); };
    const int here{ distances[index(x, y)] };
    std::pair<int, int> best{ x, y };
    int bestDistance{ here };
    const int dx[]{ 0, 0, -1, 1 }, dy[]{ -1, 1, 0, 0 };          // up, down, left, right
    for (int d{ 0 }; d < 4; ++d)
    {
        const int nx{ x + dx[d] }, ny{ y + dy[d] };
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        const int value{ distances[index(nx, ny)] };
        if (value < 0) continue;                                  // a wall or unreachable
        if (bestDistance < 0 || value < bestDistance) { best = { nx, ny }; bestDistance = value; }
    }
    if (here < 0 || bestDistance >= here) return { x, y };      // nowhere closer to go
    return best;
}

