// 7 x 4:  #######
//         #.....#
//         #.###.#
//         #.#@..#
const std::string cave{ "#######" "#.....#" "#.###.#" "#.#...#" };
TEST("distances around a wall")
{
    const auto d{ distanceMap(cave, 7, 3, 3) };
    CHECK_EQ(d[3 * 7 + 3], 0);
    CHECK_EQ(d[3 * 7 + 5], 2);
    CHECK_EQ(d[1 * 7 + 5], 4);
    CHECK_EQ(d[1 * 7 + 1], 8);
    CHECK_EQ(d[3 * 7 + 1], 10);
    CHECK_EQ(d[0], -1);
}
TEST("unreachable tiles stay -1") { const std::string m{ "..#.." }; const auto d{ distanceMap(m, 5, 0, 0) }; CHECK_EQ(d[1], 1); CHECK_EQ(d[3], -1); CHECK_EQ(d[4], -1); }
TEST("a monster walks downhill around the wall")
{
    const auto d{ distanceMap(cave, 7, 3, 3) };
    int x{ 1 }, y{ 3 }, steps{ 0 };
    while (!(x == 3 && y == 3) && steps < 20) { const auto [nx, ny] = nextStep(cave, 7, d, x, y); x = nx; y = ny; ++steps; }
    CHECK_EQ(steps, 10);
}
TEST("ties go to the first direction checked") { const std::string m{ "...." "...." "...." }; const auto d{ distanceMap(m, 4, 1, 0) }; const auto [x, y] = nextStep(m, 4, d, 2, 1); CHECK_EQ(x, 2); CHECK_EQ(y, 0); }
TEST("at the goal, stay") { const auto d{ distanceMap(cave, 7, 3, 3) }; const auto [x, y] = nextStep(cave, 7, d, 3, 3); CHECK_EQ(x, 3); CHECK_EQ(y, 3); }
TEST("cut off, stay") { const std::string m{ "..#.." }; const auto d{ distanceMap(m, 5, 0, 0) }; const auto [x, y] = nextStep(m, 5, d, 4, 0); CHECK_EQ(x, 4); CHECK_EQ(y, 0); }
TEST("a goal in a wall gives nothing") { const auto d{ distanceMap(cave, 7, 0, 0) }; bool all{ true }; for (int v : d) all = all && v == -1; CHECK(all); }

